    internal static int InPage(emon.Port.Cells wd, emon.Port.Cells gl, emon.Port.Cells fo, emon.Port.Cells et, emon.Port.Cells lt, int page, emon.Port.Cells sc, emon.Port.Cells sq, emon.Port.Cells tm, emon.Port.Cells ii) {
