        int i = 0;
        int s = 0;
        int n = 0;
        int got = 0;
        int c = 0;
        int r0 = 0;
        InCollect(wd, lt, page, sc, tm);
        n = emon.Port.CellsLen(sc);
        if (n == 0) {
            return 0;
        }
        med = InMedian(tm);
        if (med < 1) {
            return 0;
        }
        i = 0;
        while (i < n) {
            c = emon.Port.CellsAt(sc, i);
            if ((Evidence.LnGet(lt, c, Evidence.LhCount()) == 1) && ((InLsize(wd, lt, c) * 10) >= (InMinPage * med)) && InWordOk(wd, et, Evidence.LnGet(lt, c, Evidence.LhFirst()))) {
