                    r0 = emon.Port.CellsLen(ii) / IiStride;
                    got = InTryDrop(wd, lt, fo, et, sc, sq, ii, c, s);
                    if (got == 1) {
                        int rr = r0 * IiStride;
                        InApply(lt, sq, emon.Port.CellsAt(ii, rr + IiForm), emon.Port.CellsAt(ii, rr + IiLines), c, s);
                        emon.Port.CellsSet(lt, (c * 16) + Evidence.LhPage(), 0);
                    }
                    s += 1;
                }
            }
            i += 1;
        }
        InCollect(wd, lt, page, sc, tm);
        n = emon.Port.CellsLen(sc);
        i = 0;
        while (i < n) {
            c = emon.Port.CellsAt(sc, i);
