    internal static int InLower(int cp) {
        if ((cp >= 65) && (cp <= 90)) {
            return cp + 32;
        }
        return cp;
    }
    public static int InLang(emon.Port.Cells loc) {
        // The language of a locale tag held as code points (`en`, `en-US`, `DE_ch`): LG_NONE for no tag, else an LG_
        // code, LG_OTHER for a language without a table.
        int n = emon.Port.CellsLen(loc);
        if (n < 2) {
            return LgNone;
        }
        int a = InLower(emon.Port.CellsAt(loc, 0));
        int b = InLower(emon.Port.CellsAt(loc, 1));
        int c = 45;
        if (n > 2) {
            c = emon.Port.CellsAt(loc, 2);
        }
        if ((c != 45) && (c != 95)) {
            return LgOther;
        }
        if ((a == 101) && (b == 110)) {
            return LgEn;
        }
        if ((a == 100) && (b == 101)) {
            return LgDe;
        }
        if ((a == 102) && (b == 114)) {
            return LgFr;
        }
        if ((a == 101) && (b == 115)) {
            return LgEs;
        }
        if ((a == 112) && (b == 116)) {
            return LgPt;
        }
        if ((a == 105) && (b == 116)) {
            return LgIt;
        }
        if ((a == 110) && (b == 108)) {
            return LgNl;
        }
        return LgOther;
    }
    internal static bool InOneLetter(int lang, int cp) {
        // Is the upper-case code point cp a word of its own in language `lang` (the union of the tables when LG_NONE or
        // LG_OTHER)?
        int i = 0;
        int cur = -1;
        while (i < 38) {
            int v = InOne[i];
            if (cur < 0) {
                cur = v;
            } else if (v == 0) {
                cur = -1;
            } else if ((v == cp) && ((cur == lang) || ((lang == LgNone) || (lang == LgOther)))) {
                return 1 == 1;
            }
            i += 1;
        }
        return 0 == 1;
    }
    internal static bool InFollows(int lang, int kind, int letter, emon.Port.Cells et, int ts, int tl) {
        // Is the word et[ts, ts+tl) (lower-cased) in the list `kind` (1 the words a one-letter word is followed by, 2 the
        // rest of a word the letter begins) for (lang, letter)?
        int n = 685;
        int i = 0;
        int inlang = 0;
        int inlet = 0;
        int w = 0;
        int k = 0;
        int same = 0;
        while (i < n) {
            int v = InFollow[i];
            if (inlang == 0) {
                if (v == 0) {
                    return 0 == 1;
                }
                inlang = v;
                inlet = 0;
                i += 1;
            } else if (inlet == 0) {
                if (v == 0) {
                    inlang = 0;
                    i += 1;
                } else {
                    inlet = v;
                    i += 1;
                }
            } else {
                if (v == 0) {
                    inlet = 0;
                    i += 1;
                } else {
                    w = v;
                    if ((inlang == ((lang * 10) + kind)) && (inlet == letter) && (w == tl)) {
                        same = 1;
                        k = 0;
                        while (k < w) {
                            if (InFollow[i + (1 + k)] != InLower(emon.Port.CellsAt(et, ts + k))) {
                                same = 0;
                            }
                            k += 1;
                        }
                        if (same == 1) {
                            return 1 == 1;
                        }
                    }
                    i += 1 + w;
                }
            }
        }
        return 0 == 1;
    }
    public static int InJoin(emon.Port.Cells loc, int cp, emon.Port.Cells et, int ts, int tl) {
        // How an initial whose whole text is the code point cp (upper case or not) meets the first word of its first
        // line, et[ts, ts+tl) (an empty word is tl 0): 0 joined and sure, 1 joined and flagged low-conf, 2 a space.
        int lang = InLang(loc);
        int up = cp;
        if ((cp >= 97) && (cp <= 122)) {
            up = cp - 32;
        }
        if (!InOneLetter(lang, up)) {
            return 0;
        }
        if ((lang == LgEn) && (tl > 0)) {
            if (InFollows(lang, 1, up, et, ts, tl)) {
                return 2;
            }
            if (InFollows(lang, 2, up, et, ts, tl)) {
                return 0;
            }
        }
        return 1;
    }
    internal static int InJoinOf(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells lt, emon.Port.Cells loc, emon.Port.Cells ii, int r) {
        // How the initial of row r of `ii` meets the first word of its first line: 0 joined and sure, 1 joined and
        // flagged low-conf, 2 a space. One code point: `in-join`'s table and lists. Two or more that begin with a letter or
        // digit: a whole first word (`IT`), a space, unless it is of a script written without spaces; one that begins with
        // punctuation (`“N`) is joined. A raised initial is part of its word.
