        int c0 = InFirstCp(wd, et, iw);
        if (c0 < 0) {
            return 0;
        }
        if (ncp == 1) {
            return InJoin(loc, c0, et, Evidence.WdGet(wd, w1, Evidence.HdTstart()), Evidence.WdGet(wd, w1, Evidence.HdTlen()));
        }
        if (!InAlnum(c0)) {
            return 0;
        }
        if (InIdeo(c0)) {
            return 0;
        }
        return 2;
    }
    public static int InDetect(emon.Port.Cells wd, emon.Port.Cells gl, emon.Port.Cells fo, emon.Port.Cells et, int npages, emon.Port.Cells loc, emon.Port.Cells lt, emon.Port.Cells sc, emon.Port.Cells sq, emon.Port.Cells tm, emon.Port.Cells ii) {
        // Every page's initials. `lt` is the lines' copy (`lc-copy`): rewritten as the header says. `ii` is the table
        // of initials (stride 12); `loc` the locale tag as code points (empty for none), which decides the join. `sc sq tm`
        // are scratch. Answers the initials found.
        int nl = emon.Port.CellsLen(lt) / 16;
        int p = 1;
        int r = 0;
        int q = 0;
        emon.Port.CellsDrop(ii, 0);
        // Cell 15 is this stage's alone: whatever a producer left there is cleared.
        while (r < nl) {
            emon.Port.CellsSet(lt, (r * 16) + 15, 0);
            r += 1;
        }
        while (p <= npages) {
            InPage(wd, gl, fo, et, lt, p, sc, sq, tm, ii);
            p += 1;
        }
        q = emon.Port.CellsLen(ii) / IiStride;
        r = 0;
        while (r < q) {
            int rr = r * IiStride;
            int t = emon.Port.CellsAt(ii, rr + IiTl);
            int jn = InJoinOf(wd, et, lt, loc, ii, r);
            emon.Port.CellsSet(ii, rr + IiJoin, jn);
            if ((t >= 0) && (t < nl)) {
                int v = (r + 1) * 4;
                if (emon.Port.CellsAt(ii, rr + IiIl) < 0) {
                    v += 1;
                    if ((emon.Port.CellsAt(ii, rr + IiNcp) == Evidence.WdGet(wd, emon.Port.CellsAt(ii, rr + IiWord), Evidence.HdTlen())) && (jn != 2)) {
                        v += 2;
                    }
                }
                emon.Port.CellsSet(lt, (t * 16) + 15, v);
            }
            r += 1;
        }
        return q;
    }
    public static int InGetIi(emon.Port.Cells ii, int r, int f) {
        return emon.Port.CellsAt(ii, (r * IiStride) + f);
    }
    public static int InRow(emon.Port.Cells lt, int l) {
        // The row of `ii` whose target is row l of `lt`, -1 for none.
        if ((l < 0) || (((l + 1) * 16) > emon.Port.CellsLen(lt))) {
            return -1;
        }
        int c = emon.Port.CellsAt(lt, (l * 16) + 15);
        if (c < 4) {
            return -1;
        }
        return (c / 4) - 1;
    }
}
